    void poll(){
        double[] st=s.state();int active=s.playing()&&st[0]>=st[3]&&(int)st[2]==s.selectedPart?(int)((st[0]-st[3])/MusicTheory.barBeats(s.project.meter)):-1;
        if(active<0||active>=chordCards.size())active=-1;
        if(active!=highlightedBar){for(int i=0;i<chordCards.size();i++){android.graphics.drawable.GradientDrawable bg=StudioTheme.background(a,StudioTheme.SURFACE,14);if(i==active)bg.setStroke(a.dp(2),MainActivity.LIME);chordCards.get(i).setBackground(bg);}highlightedBar=active;}
        if(transportLabel!=null){String status=s.capturing?(st[8]==1?tr("카운트인 / 다음 마디 대기","Count-in / waiting for next bar"):tr("프레이즈 기록 중 · 파트 끝에서 저장","Recording phrase · saves at end of part")):st[0]<0?tr("1마디 카운트인","One-bar count-in"):tr("마디 ","Bar ")+(1+(int)(Math.max(0,st[0])/MusicTheory.barBeats(s.project.meter)))+" · "+s.project.bpm+" BPM"+(s.playing()?tr(" · 재생 중"," · Playing"):"");transportLabel.setText(status);}
        if(play!=null){play.setText(s.playing()?tr("일시정지","Pause"):tr("재생","Play"));((StudioButton)play).glyph(s.playing()?"pause":"play");}
        if(readout!=null)readout.setText(tr("목소리 ","Voice ")+(st[5]>=0?MusicTheory.note((int)st[5]):"—")+"\n→ "+InstrumentCatalog.GM[s.project.voice.program]+" "+(st[6]>=0?MusicTheory.note((int)st[6]):"—")+String.format(Locale.US,tr("\n입력 %.0f dB","\nInput %.0f dB"),20*Math.log10(Math.max(.00001,st[7]))));
    }
    void instrument(int track,boolean voice){Dialog dialog=new Dialog(a);LinearLayout panel=a.column();panel.setPadding(a.dp(16),a.dp(12),a.dp(16),a.dp(12));panel.setBackground(StudioTheme.background(a,MainActivity.PANEL,20));EditText search=new EditText(a);search.setTextColor(MainActivity.TEXT);search.setHintTextColor(MainActivity.MUTED);search.setHint(tr("악기 · 카테고리 검색","Search instruments or categories"));search.setSingleLine();search.setTypeface(StudioTheme.body(a));search.setPadding(a.dp(14),a.dp(12),a.dp(14),a.dp(12));search.setBackground(StudioTheme.background(a,StudioTheme.RAISED,12));panel.addView(search);final int[] category={0};List<String> cats=new ArrayList<>(Arrays.asList(tr("대표 24음색","Featured 24"),tr("전체 GM 128","All GM 128"),tr("즐겨찾기","Favorites")));cats.addAll(Arrays.asList(InstrumentCatalog.categories(a)));if(!voice)cats.add(tr("드럼 키트","Drum kits"));Button categoryButton=a.button(tr("카테고리: ","Category: ")+cats.get(0)+" ▾",()->choose(tr("악기 카테고리","Instrument category"),cats.toArray(new String[0]),category[0],n->{category[0]=n;}));panel.addView(categoryButton);ScrollView scroll=new ScrollView(a);LinearLayout list=a.column();scroll.addView(list);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));panel.addView(a.button(tr("닫기","Close"),dialog::dismiss));Set<String> favorites=new HashSet<>(a.getPreferences(0).getStringSet("gmFavorites",Collections.emptySet()));Runnable fill=()->{list.removeAllViews();String query=search.getText().toString().toLowerCase(Locale.ROOT);int cat=category[0];if(!voice&&cat==cats.size()-1){String[] kits=NativeComposer.drumKits();for(String kit:kits){int program=Integer.parseInt(kit.split(" · ")[0]);list.addView(a.button(kit,()->{selectInstrument(track,false,program,128);dialog.dismiss();}));}return;}for(int n=0;n<128;n++){int program=n;if(voice&&n>=112)continue;boolean featured=false;for(int f:InstrumentCatalog.FEATURED)if(f==n)featured=true;if(query.isEmpty()&&((cat==0&&!featured)||(cat==2&&!favorites.contains(""+n))||(cat>=3&&cat-3!=n/8)))continue;String label=InstrumentCatalog.GM[n],family=InstrumentCatalog.categories(a)[n/8];if(!query.isEmpty()&&!(label+" "+family).toLowerCase(Locale.ROOT).contains(query))continue;Button item=a.button((favorites.contains(""+n)?"★ ":"")+label+" · "+family,()->{selectInstrument(track,voice,program,0);dialog.dismiss();});item.setOnLongClickListener(view->{String id=""+program;if(!favorites.add(id))favorites.remove(id);a.getPreferences(0).edit().putStringSet("gmFavorites",favorites).apply();item.setText((favorites.contains(id)?"★ ":"")+label+" · "+family);return true;});list.addView(item,new LinearLayout.LayoutParams(-1,-2));}};categoryButton.setOnClickListener(v->choose(tr("악기 카테고리","Instrument category"),cats.toArray(new String[0]),category[0],n->{category[0]=n;categoryButton.setText(tr("카테고리: ","Category: ")+cats.get(n)+" ▾");fill.run();}));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){fill.run();}public void afterTextChanged(Editable e){}});fill.run();dialog.setContentView(panel);dialog.show();dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setLayout(Math.min(a.root.getWidth(),a.dp(520)),Math.max(a.dp(250),(int)(a.root.getHeight()*.82f)));}
